head.script:
scwin.onpageload = function () {
    console.log("모듈 마켓플레이스 페이지가 로드되었습니다.");

    // 팝업 레이어 초기화
    scwin.createPopupLayer();

    // 구독 상태 디버깅
    scwin.debugSubscriptionState();

    scwin.loadModuleList();
};

// 팝업 레이어 생성 함수
scwin.createPopupLayer = function () {
    if (document.getElementById('customAlertPopup')) return;
    var popupHtml = `
        <div id="customAlertPopup" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 9999; display: none; align-items: center; justify-content: center; font-family: 'Pretendard', sans-serif;">
            <div style="background: white; padding: 24px; border-radius: 8px; box-shadow: 0 5px 15px rgba(0,0,0,0.3); min-width: 320px; max-width: 450px; text-align: center; box-sizing: border-box;">
                <div id="popupMessage" style="margin-bottom: 24px; font-size: 16px; line-height: 1.6; color: #333; white-space: pre-wrap; word-break: break-word;"></div>
                <div>
                    <button id="popupConfirm" style="background: #007bff; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">확인</button>
                    <button id="popupCancel" style="background: #6c757d; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">취소</button>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }
    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(true); };
        cancelBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(false); };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(); };
    }
    popup.style.display = 'flex';
};

scwin.loadModuleList = function () {
    console.log("GET 방식으로 모듈 목록 조회 시작");
    const tenantId = $p.getParameter("tenant");

    $.ajax({
        url: '/InsWebApp/MarketplaceModuleList.pwkjson',
        type: 'GET',
        data: { pageSize: 50, pageIndex: 1, tenantId: tenantId },
        success: function (response) {
            console.log("모듈 목록 조회 성공:", response);
            scwin.handleModuleListSuccess(response);
        },
        error: function (xhr, status, error) {
            console.error("모듈 목록 조회 실패:", error);
            if (xhr.status === 500 || error.includes("세션")) {
                scwin.loadModuleListFallback();
            } else {
                scwin.showPopup("모듈 목록을 불러오는데 실패했습니다: " + error);
            }
        }
    });
};

// 모듈 목록 조회 성공 처리
scwin.handleModuleListSuccess = function (response) {
    var moduleList = [];
    if (response.moduleListVo && response.moduleListVo.moduleVoList) {
        moduleList = response.moduleListVo.moduleVoList;
    } else if (response.moduleVoList) {
        moduleList = response.moduleVoList;
    }
    if (moduleList && moduleList.length > 0) {
        scwin.loadSubscriptionStatus(moduleList);
    }
};

scwin.loadSubscriptionStatus = function (moduleList) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId) {
        console.log("테넌트 ID가 없어 구독 상태 조회를 건너뜁니다.");
        scwin.processModuleList(moduleList);
        return;
    }

    const subscribedModulesKey = `subscribedModules_${tenantId}`;
    const subscribedModules = JSON.parse(localStorage.getItem(subscribedModulesKey) || '[]');
    console.log("로컬 스토리지에서 구독 상태 로드:", subscribedModules);

    moduleList.forEach(function (module) {
        const moduleCode = module.code || module.moduleId;
        const moduleId = module.moduleId || module.id;
        module.subscribed = subscribedModules.includes(moduleCode) || subscribedModules.includes(String(moduleId)) || subscribedModules.includes(moduleId);
    });

    scwin.processModuleList(moduleList);
};

scwin.processModuleList = function (moduleList) {
    moduleList.forEach(function (module, index) {
        const id = module.code || module.moduleId;

        // 아이콘 할당
        var iconList = ["chat", "video", "canvas", "attendance", "drowsy", "absent", "screen", "mic", "camera"];
        module.icon = iconList[index % iconList.length]; // 기본값
        switch (id) {
            case 'CHAT': module.icon = "chat"; break;
            case 'VIDEO': module.icon = "video"; break;
            case 'CANVAS': module.icon = "canvas"; break;
            case 'QUIZ': module.icon = "attendance"; break;
            case 'FACEAI': module.icon = "drowsy"; break;
            case 'PARTICIPANTS': module.icon = "absent"; break;
            case 'ABSENT': module.icon = "absent"; break;
            case 'SCREEN': module.icon = "screen"; break;
            case 'MIC': module.icon = "mic"; break;
            case 'CAMERA': module.icon = "camera"; break;
            case 'ATTENDANCE': module.icon = "attendance"; break;
        }

        // 카테고리 할당
        switch (id) {
            case 'VIDEO': case 'CHAT': case 'CANVAS': case 'SCREEN':
                module.category = 'meeting'; break;
            case 'FACEAI': case 'QUIZ': case 'ATTENDANCE':
                module.category = 'education'; break;
            case 'PARTICIPANTS': case 'ABSENT': case 'MIC': case 'CAMERA':
                module.category = 'management'; break;
            default:
                module.category = 'etc';
        }

        const randomRating = (Math.random() + 4.0).toFixed(1);
        module.ratingValue = randomRating;
        module.ratingStars = `★★★★☆ ${randomRating}`;

        if (module.price) {
            module.formattedPrice = "₩" + parseInt(module.price).toLocaleString();
        }
    });

    const paidModules = moduleList.filter(m => m.price && parseInt(m.price, 10) > 0);
    scwin.createManualModuleList(paidModules);
    scwin.initializePopularModules(moduleList);
};

scwin.allModules = []; // 필터링을 위한 전역 변수

scwin.initializePopularModules = function (moduleList) {
    scwin.allModules = moduleList; // 아이콘, 카테고리, 별점 등 모든 정보가 이미 포함된 리스트
    scwin.createPopularModuleGrid(scwin.allModules);
    console.log("카테고리가 추가된 모듈 목록:", scwin.allModules);
};

scwin.createManualModuleList = function (moduleList) {
    var moduleListContainer = document.querySelector(".module-list");
    if (!moduleListContainer) {
        console.error("모듈 리스트 컨테이너를 찾을 수 없습니다");
        return;
    }

    var html = "";
    moduleList.forEach(function (module, index) {
        var iconSvg = scwin.getIconSvg(module.icon);
        const moduleId = module.moduleId || module.id;
        const moduleCode = module.code || module.moduleId;
        const moduleName = module.name || module.title || '모듈';

        var buttonHtml = '';
        const isPaidModule = module.price && parseInt(String(module.price).replace(/[^0-9]/g, ''), 10) > 0;
        if(isPaidModule) {
            buttonHtml = `<button class="subscribe-btn ${module.subscribed ? 'subscribed' : ''}" 
                            data-module-id="${moduleId}" 
                            data-module-code="${moduleCode}"
                            data-module-name="${moduleName}"
                            data-subscribed="${module.subscribed}" 
                            style="width:93px;height:28px;background-color:${module.subscribed ? '#6c757d' : '#3674B5'};color:#FFFFFF;border-radius:6px;border:none;cursor:pointer;font-size:12px;">
                            ${module.subscribed ? '구독중' : '구독하기'}
                        </button>`;
        }

        html += `<div class="module-card" style="border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; display: flex; align-items: center; gap: 16px; margin-bottom: 16px;">
                    <div class="module-icon ${module.icon}" style="flex-shrink: 0; width: 48px; height: 48px; border-radius: 50%; display:flex; align-items:center; justify-content:center; ${scwin.getIconStyle(module.icon)}">
                        ${iconSvg}
                    </div>
                    <div class="module-card-info" style="flex-grow: 1;">
                        <div class="title" style="font-weight: 600; font-size: 1rem; color: #1f2937;">${moduleName}</div>
                        <div class="desc" style="font-size: 0.875rem; color: #6b7280; margin-top: 4px;">${module.description || ''}</div>
                        <div class="price" style="font-size: 1rem; font-weight: 600; color: #374151; margin-top: 8px;">${module.formattedPrice || ''}</div>
                    </div>
                    <div class="module-card-actions" style="text-align: right;">
                        <div class="rating" style="font-size: 0.875rem; color: #f59e0b; margin-bottom: 8px;">${module.ratingStars}</div>
                        ${buttonHtml}
                    </div>
                 </div>`;
    });

    moduleListContainer.innerHTML = html;
    scwin.bindSubscribeEvents();
};


scwin.createPopularModuleGrid = function (moduleList) {
    var gridContainer = document.querySelector(".marketplace-grid");
    if (!gridContainer) {
        console.error("인기 모듈 그리드 컨테이너를 찾을 수 없습니다.");
        return;
    }

    var html = "";
    var displayList = moduleList.slice(0, 4);

    displayList.forEach(function (module) {
        const iconSvg = scwin.getIconSvg(module.icon);
        const moduleId = module.moduleId || module.id;
        const moduleCode = module.code || module.moduleId;
        const moduleName = module.name || module.title || '모듈';


        let buttonHtml = '';
        const isPaidModule = module.price && parseInt(String(module.price).replace(/[^0-9]/g, ''), 10) > 0;
        if (isPaidModule) {
            buttonHtml = `<button class="subscribe-btn ${module.subscribed ? 'subscribed' : ''}"
                            data-module-id="${moduleId}" 
                            data-module-code="${moduleCode}"
                            data-module-name="${moduleName}"
                            data-subscribed="${module.subscribed}"
                            style="width: 100%; height: 29px; background-color:${module.subscribed ? '#6c757d' : '#3674B5'}; color:#FFFFFF; border-radius: 6px; border: none; cursor: pointer;">
                            ${module.subscribed ? '구독중' : '구독하기'}
                        </button>`;
        }

        const iconHtml = `
            <div class="module-icon" style="flex-shrink: 0; width: 48px; height: 48px; border-radius: 50%; display:flex; align-items:center; justify-content:center; ${scwin.getIconStyle(module.icon)}">
                ${scwin.getIconSvg(module.icon)}
            </div>`;

        html += `
            <div class="grid-module-card" style="padding: 16px; display: flex; flex-direction: column; gap: 8px;">
                <div class="grid-module-card-header" style="display:flex; align-items: center; gap: 12px;">
                    ${iconHtml}
                    <div class="title" style="color:#000000; font-weight: 600; font-size: 0.9rem;">${moduleName}</div>
                </div>
                <div class="rating" style="color: #f59e0b; font-size: 0.8rem;">${module.ratingStars}</div>
                <div class="price" style="font-size: 1rem; font-weight: 700; color: #111827; margin-top: auto;">${module.formattedPrice || '무료'}</div>
                <div style="padding-top: 8px;">
                    ${buttonHtml}
                </div>
            </div>`;
    });
    gridContainer.innerHTML = html;
};



scwin.loadModuleListFallback = function () {
    console.log("대체 서비스로 모듈 목록 조회 재시도");
    const tenantId = $p.getParameter("tenant");
    $.ajax({
        url: '/InsWebApp/ModuleList.pwkjson',
        type: 'POST', contentType: 'application/json',
        data: JSON.stringify({ pageSize: 50, pageIndex: 1, tenantId: tenantId }),
        success: function (response) { scwin.handleModuleListSuccess(response); },
        error: function (xhr, status, error) { scwin.showPopup("모듈 목록을 불러오는데 실패했습니다: " + error); }
    });
};

scwin.updateSubscriptionStatus = function (moduleId, moduleCode, isSubscribed) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId) return;
    const subscribedModulesKey = `subscribedModules_${tenantId}`;
    let subscribedModules = JSON.parse(localStorage.getItem(subscribedModulesKey) || '[]');
    if (isSubscribed) {
        if (!subscribedModules.includes(String(moduleId))) { subscribedModules.push(String(moduleId)); }
        if (moduleCode && !subscribedModules.includes(moduleCode)) { subscribedModules.push(moduleCode); }
    } else {
        subscribedModules = subscribedModules.filter(id => id !== String(moduleId) && id !== moduleCode && id !== moduleId);
    }
    localStorage.setItem(subscribedModulesKey, JSON.stringify(subscribedModules));
};

scwin.debugSubscriptionState = function () {
    const tenantId = $p.getParameter("tenant");
    if (tenantId) {
        const subscribedModulesKey = `subscribedModules_${tenantId}`;
        console.log("저장된 구독 정보:", localStorage.getItem(subscribedModulesKey));
    }
};

scwin.bindSubscribeEvents = function () {
    var moduleListContainer = document.querySelector(".marketplace-wrapper");
    if (moduleListContainer) {
        moduleListContainer.removeEventListener('click', scwin.handleSubscribeClick);
        moduleListContainer.addEventListener('click', scwin.handleSubscribeClick);
    }
};

scwin.handleSubscribeClick = function (event) {
    if (event.target.classList.contains('subscribe-btn')) {
        const button = event.target;
        const moduleId = button.getAttribute('data-module-id');
        const isSubscribed = button.getAttribute('data-subscribed') === 'true';
        if (moduleId) {
            if (isSubscribed) {
                scwin.promptUnsubscribe(moduleId, button);
            } else {
                scwin.subscribeModule(moduleId, button);
            }
        }
    }
};

scwin.promptUnsubscribe = function (moduleId, buttonElement) {
    const moduleName = buttonElement.getAttribute('data-module-name') || '모듈';
    scwin.showPopup(moduleName + " 모듈의 구독을 해지하시겠습니까?", true, function (confirmed) {
        if (confirmed) {
            scwin.unsubscribeModule(moduleId, buttonElement);
        }
    });
};

scwin.subscribeModule = function (moduleId, buttonElement) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId) { scwin.showPopup("테넌트 정보가 없어 구독할 수 없습니다."); return; }
    const moduleName = buttonElement.getAttribute('data-module-name') || '모듈';
    $.ajax({
        url: '/InsWebApp/TMD0001Subscribe.pwkjson',
        type: 'POST', contentType: 'application/json',
        data: JSON.stringify({ tenantModuleVo: { moduleId: moduleId, tenantId: tenantId } }),
        success: function (response) {
            scwin.showPopup(moduleName + " 모듈이 구독되었습니다!");
            buttonElement.textContent = '구독중';
            buttonElement.style.backgroundColor = '#6c757d';
            buttonElement.classList.add('subscribed');
            buttonElement.setAttribute('data-subscribed', 'true');
            const moduleCode = buttonElement.getAttribute('data-module-code');
            scwin.updateSubscriptionStatus(moduleId, moduleCode, true);
        },
        error: function (xhr, status, error) {
            const errorMsg = xhr.responseJSON?.elHeader?.resMsg || error;
            scwin.showPopup(moduleName + " 모듈 구독에 실패했습니다: " + errorMsg);
        }
    });
};

scwin.unsubscribeModule = function (moduleId, buttonElement) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId) { scwin.showPopup("테넌트 정보가 없어 구독을 해지할 수 없습니다."); return; }
    const moduleName = buttonElement.getAttribute('data-module-name') || '모듈';
    $.ajax({
        url: '/InsWebApp/TMD0001Unsubscribe.pwkjson',
        type: 'POST', contentType: 'application/json',
        data: JSON.stringify({ tenantModuleVo: { moduleId: moduleId, tenantId: tenantId } }),
        success: function (response) {
            scwin.showPopup(moduleName + " 모듈 구독이 해지되었습니다!");
            buttonElement.textContent = '구독하기';
            buttonElement.style.backgroundColor = '#3674B5';
            buttonElement.classList.remove('subscribed');
            buttonElement.setAttribute('data-subscribed', 'false');
            const moduleCode = buttonElement.getAttribute('data-module-code');
            scwin.updateSubscriptionStatus(moduleId, moduleCode, false);
        },
        error: function (xhr, status, error) {
            const errorMsg = xhr.responseJSON?.elHeader?.resMsg || error;
            scwin.showPopup(moduleName + " 모듈 구독 해지에 실패했습니다: " + errorMsg);
        }
    });
};

scwin.btn_filter_onclick = function (filterType) {
    var filterTabs = document.querySelectorAll('.filter-tabs .w2_button');
    filterTabs.forEach(function (tab) { tab.classList.remove('active'); });
    event.target.classList.add('active');

    let filteredList = (filterType === 'all')
        ? scwin.allModules
        : scwin.allModules.filter(module => module.category === filterType);

    scwin.createPopularModuleGrid(filteredList);
};

scwin.getIconStyle = function (iconType) {
    var styles = {
        'chat': 'background-color: #e0e7ff; color: #3674B5;', 'video': 'background-color: #fce7f3; color: #be185d;',
        'canvas': 'background-color: #ecfdf5; color: #059669;', 'attendance': 'background-color: #fef3c7; color: #d97706;',
        'drowsy': 'background-color: #fce7f3; color: #db2777;', 'absent': 'background-color: #fffbeb; color: #d97706;',
        'screen': 'background-color: #f0f9ff; color: #0369a1;', 'mic': 'background-color: #fffbeb; color: #d97706;',
        'camera': 'background-color: #fef2f2; color: #dc2626;'
    };
    return styles[iconType] || 'background-color: #fce7f3; color: #db2777;';
};

scwin.getIconSvg = function (iconType) {
    var svgs = {
        'chat': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M8.625 12a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H8.25m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H12m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0h-.375M21 12c0 4.556-4.03 8.25-9 8.25a9.764 9.764 0 01-2.555-.337A5.972 5.972 0 015.41 20.97a5.969 5.969 0 01-.474-.065 4.48 4.48 0 00.978-2.025c.09-.457-.133-.901-.467-1.226C3.93 16.178 3 14.189 3 12c0-4.556 4.03-8.25 9-8.25s9 3.694 9 8.25z" /></svg>',
        'video': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="m15.75 10.5 4.72-4.72a.75.75 0 0 1 1.28.53v11.38a.75.75 0 0 1-1.28.53l-4.72-4.72M4.5 18.75h9a2.25 2.25 0 0 0 2.25-2.25v-9a2.25 2.25 0 0 0-2.25-2.25h-9A2.25 2.25 0 0 0 2.25 7.5v9a2.25 2.25 0 0 0 2.25 2.25Z" /></svg>',
        'canvas': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M9.53 16.122a3 3 0 00-5.78 1.128 2.25 2.25 0 01-2.4 2.245 4.5 4.5 0 008.4-2.245c0-.399-.078-.78-.22-1.128zm0 0a15.998 15.998 0 003.388-1.62m-5.043-.025a15.994 15.994 0 011.622-3.395m3.42 3.42a15.995 15.995 0 004.764-4.648l3.876-5.814a1.151 1.151 0 00-1.597-1.597L14.146 6.32a15.996 15.996 0 00-4.649 4.763m3.42 3.42a6.776 6.776 0 00-3.42-3.42" /></svg>',
        'attendance': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>',
        'drowsy': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z" /></svg>',
        'absent': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>',
        'screen': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M9 17.25v1.007a3 3 0 01-.879 2.122L7.5 21h9l-.621-.621A3 3 0 0115 18.257V17.25m6-12V15a2.25 2.25 0 01-2.25 2.25H5.25A2.25 2.25 0 013 15V5.25m18 0A2.25 2.25 0 0018.75 3H5.25A2.25 2.25 0 003 5.25m18 0V12a2.25 2.25 0 01-2.25 2.25H5.25A2.25 2.25 0 013 12V5.25" /></svg>',
        'mic': '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" style="width: 24px; height: 24px;"><path stroke-linecap="round" stroke-linejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" /></svg>',
